/**
 * Tests for readPdfText.js with real PDF files, read by PDF.js (legacy
 * build, for Node) — run with `npm test`.
 *
 * The files are in sample-data/ and test-fixtures/pdf/, generated by
 * scripts/make-sample-pdfs.mjs. The last part checks that the committed
 * files still match the generator, and that the sample PDF prices exactly
 * like the sample CSV (Rs.5,339).
 */

import { test, describe } from 'node:test'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import * as pdfjs from 'pdfjs-dist/legacy/build/pdf.mjs'
import { readPdfText, looksLikePdf, PDF_READ_MESSAGES, MAX_PDF_BYTES, MAX_PDF_PAGES } from './readPdfText.js'
import { parseCartPdf, PDF_FILE_ERRORS } from '../engine/pdfCartParser.js'
import { parseCartCSV, parseRulesCSV } from '../engine/csvParser.js'
import { priceCart } from '../engine/discountEngine.js'
import { buildPdf, fixtureFiles } from '../../scripts/pdfFixtures.mjs'

const file = (path) => new Uint8Array(readFileSync(new URL(`../../${path}`, import.meta.url)))
const fixture = (name) => file(`test-fixtures/pdf/${name}`)

/** Reads and parses a file the way the app will: bytes → text → CartItems. */
async function cartFromPdf(bytes) {
  const read = await readPdfText(bytes, pdfjs)
  assert.equal(read.ok, true, `could not read the PDF: ${read.reason}`)
  return parseCartPdf(read.pages)
}

describe('readPdfText: files that cannot be used', () => {
  const cases = [
    ['password.pdf', 'password'],
    ['scanned.pdf', 'scanned'],
    ['empty.pdf', 'empty'],
    ['damaged.pdf', 'damaged'],
    ['not-a-pdf.pdf', 'not_pdf'],
  ]
  for (const [name, reason] of cases) {
    test(`${name} → ${reason}`, async () => {
      assert.deepEqual(await readPdfText(fixture(name), pdfjs), { ok: false, reason })
    })
  }

  test('every reason has a customer message', () => {
    for (const reason of ['password', 'scanned', 'empty', 'damaged', 'not_pdf', 'too_large', 'too_many_pages', 'unreadable']) {
      assert.equal(typeof PDF_READ_MESSAGES[reason], 'string', reason)
    }
  })

  test('a file over 5 MB is refused before it is opened', async () => {
    const big = new Uint8Array(MAX_PDF_BYTES + 1)
    big.set([0x25, 0x50, 0x44, 0x46, 0x2d])
    assert.deepEqual(await readPdfText(big, pdfjs), { ok: false, reason: 'too_large' })
  })

  test(`a PDF with more than ${MAX_PDF_PAGES} pages is refused`, async () => {
    const pages = Array.from({ length: MAX_PDF_PAGES + 1 }, (_, i) => ({ texts: [{ x: 50, y: 700, str: `Page ${i + 1}` }] }))
    assert.deepEqual(await readPdfText(new Uint8Array(buildPdf({ pages })), pdfjs), { ok: false, reason: 'too_many_pages' })
  })

  test('a PDF of exactly the page limit is read', async () => {
    const pages = Array.from({ length: MAX_PDF_PAGES }, () => ({ texts: [{ x: 50, y: 700, str: 'Hello' }] }))
    const result = await readPdfText(new Uint8Array(buildPdf({ pages })), pdfjs)
    assert.equal(result.ok, true)
    assert.equal(result.pages.length, MAX_PDF_PAGES)
  })

  test('an empty file is not a PDF', async () => {
    assert.deepEqual(await readPdfText(new Uint8Array(0), pdfjs), { ok: false, reason: 'not_pdf' })
  })
})

describe('readPdfText: the text and its positions', () => {
  test('the sample cart gives each piece of text with where it sits', async () => {
    const result = await readPdfText(file('sample-data/cart.pdf'), pdfjs)
    assert.equal(result.ok, true)
    assert.equal(result.pages.length, 1)
    const items = result.pages[0].items
    // No blank pieces: PDF.js's spacing entries are dropped
    assert.ok(items.every((item) => item.str.trim() === item.str && item.str !== ''))
    const header = items.find((item) => item.str === 'Base Price')
    assert.deepEqual({ x: header.x, y: header.y, fontSize: header.fontSize }, { x: 465, y: 728, fontSize: 10 })
    assert.ok(header.width > 40 && header.width < 60)
    assert.ok(items.some((item) => item.str === 'Order #OP-9921 | Date: 15 Jan 2025'))
  })

  test('the bytes passed in are left intact (PDF.js gets a copy)', async () => {
    const bytes = file('sample-data/cart.pdf')
    const before = bytes.slice()
    await readPdfText(bytes, pdfjs)
    assert.equal(bytes.byteLength, before.byteLength)
    assert.deepEqual(bytes, before)
  })

  test('an ArrayBuffer is accepted, as the browser gives one', async () => {
    const bytes = file('sample-data/cart.pdf')
    const result = await readPdfText(bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength), pdfjs)
    assert.equal(result.ok, true)
  })

  test('looksLikePdf finds the signature near the start only', () => {
    const encode = (text) => new TextEncoder().encode(text)
    assert.equal(looksLikePdf(encode('%PDF-1.7\n...')), true)
    assert.equal(looksLikePdf(encode(`${' '.repeat(100)}%PDF-1.4`)), true)
    assert.equal(looksLikePdf(encode(`${' '.repeat(2000)}%PDF-1.4`)), false)
    assert.equal(looksLikePdf(encode('item_id,product')), false)
    assert.equal(looksLikePdf(encode('%PDF')), false)
  })
})

describe('real PDFs, end to end (bytes → text → CartItems)', () => {
  test('the sample PDF gives exactly the same cart as the sample CSV', async () => {
    const fromPdf = await cartFromPdf(file('sample-data/cart.pdf'))
    const fromCsv = parseCartCSV(readFileSync(new URL('../../sample-data/cart.csv', import.meta.url), 'utf8'))
    assert.deepEqual(fromPdf, { data: fromCsv.data, errors: [], notes: [], fileError: null })
  })

  test('the sample PDF with the sample rules prices to Rs.5,339', async () => {
    const { data } = await cartFromPdf(file('sample-data/cart.pdf'))
    const rules = parseRulesCSV(readFileSync(new URL('../../sample-data/rules.csv', import.meta.url), 'utf8'))
    const priced = priceCart(data, rules.data)
    assert.deepEqual(priced.items.map((r) => [r.itemId, r.finalPrice, r.reasoning]), [
      ['ITEM-01', 1104, 'Platform offer: 15% off'],
      ['ITEM-02', 629, 'Brand offer: Rs.150 off + Platform offer: 10% off'],
      ['ITEM-03', 509, 'Platform offer: 15% off'],
      ['ITEM-04', 2499, 'No offers available'],
      ['ITEM-05', 382, 'Platform offer: 15% off'],
      ['ITEM-06', 809, 'Platform offer: 10% off'],
    ])
    assert.equal(priced.subtotal, 5932)
    assert.equal(priced.cartDiscount, 593)
    assert.equal(priced.finalTotal, 5339)
  })

  for (const name of ['multi-page.pdf', 'reordered-columns.pdf', 'extra-columns.pdf']) {
    test(`${name} gives the same six items as the sample`, async () => {
      const sample = await cartFromPdf(file('sample-data/cart.pdf'))
      assert.deepEqual(await cartFromPdf(fixture(name)), sample)
    })
  }

  test('price-formats.pdf reads every price format', async () => {
    const { data, errors } = await cartFromPdf(fixture('price-formats.pdf'))
    assert.deepEqual(errors, [])
    assert.deepEqual(data.map((item) => item.basePrice), [1299, 849, 599, 2499, 449, 123456])
  })

  test('malformed-rows.pdf loads the good rows and explains every skipped one', async () => {
    const result = await cartFromPdf(fixture('malformed-rows.pdf'))
    assert.deepEqual(result.data, [
      { itemId: 'ITEM-01', product: 'Handwoven Cushion Cover (Set of 2)', brand: 'Natura Casa', platform: 'Amazon India', basePrice: 1299 },
      { itemId: 'ITEM-02', product: 'Bed Sheet Set', brand: 'Natura Casa', platform: 'Flipkart', basePrice: 849 },
    ])
    assert.deepEqual(result.errors, [
      'Row 2 (Wall Shelf): missing Brand, Platform',
      'Row 3 (Ceramic Vase): Base Price "Rs.24,99" is not a readable amount (for example Rs.1,299)',
      'Row 4 (Desk Lamp): missing Brand, Platform, Base Price',
      'Row 5 (Cutting Board): Base Price "TBD" is not a readable amount (for example Rs.1,299)',
      'Row 6 (Desk Organiser): Base Price must be at least Rs.1, got "Rs.0"',
    ])
    assert.deepEqual(result.notes, ['The "Total Rs.5,095" line was not read as an item; totals are calculated from the items.'])
    assert.equal(result.fileError, null)
  })

  test('header-only.pdf reports no rows', async () => {
    assert.equal((await cartFromPdf(fixture('header-only.pdf'))).fileError, PDF_FILE_ERRORS.no_rows)
  })

  test('no-table.pdf reports no cart table', async () => {
    assert.equal((await cartFromPdf(fixture('no-table.pdf'))).fileError, PDF_FILE_ERRORS.no_table)
  })
})

describe('committed PDFs match the generator', () => {
  for (const { path, bytes } of fixtureFiles()) {
    test(path, () => {
      assert.deepEqual(file(path), new Uint8Array(bytes), `run: node scripts/make-sample-pdfs.mjs`)
    })
  }
})
